                            Id = new Guid("2a0a0001-0000-4000-8000-000000000017"),
                            BestTimeToVisit = "april-oktobar",
                            Description = "Počitelj je izuzetno dobro očuvano srednjovjekovno i osmansko naselje na strmoj obali Neretve, sa kamenom kulom, Hadži-Alijinom džamijom iz 16. stoljeća i uskim stepeništima koja se penju kroz staro jezgro. Od 1960-ih grad je poznat i kao umjetnička kolonija, koja mu je donijela dodatni sloj kulturnog života uz srednjovjekovnu arhitekturu.",
                            DestinationId = new Guid("1a0a0001-0000-4000-8000-000000000009"),
                            LanguageCode = "bs"
                        },
                        new
                        {
                            Id = new Guid("2a0a0001-0000-4000-8000-000000000018"),
                            BestTimeToVisit = "April-October",
                            Description = "Počitelj is an exceptionally well-preserved medieval and Ottoman-era settlement perched above the Neretva River, with a stone tower, the 16th-century Hadži-Alija Mosque, and narrow stepped lanes climbing through the old core. Since the 1960s the town has also been known as an artists' colony, adding a layer of living culture to its medieval architecture.",
                            DestinationId = new Guid("1a0a0001-0000-4000-8000-000000000009"),
                            LanguageCode = "en"
                        },
                        new
