                            Id = new Guid("2a0a0001-0000-4000-8000-000000000019"),
                            BestTimeToVisit = "maj-oktobar",
                            Description = "Višegrad je nosilac Mehmed-paša Sokolović mosta iz 1577. godine, remek-djela osmanske arhitekture pod zaštitom UNESCO-a, koji je Ivo Andrić ovjekovječio u romanu \"Na Drini ćuprija\" za koji je dobio Nobelovu nagradu. U blizini se nalazi i Andrićgrad, kamena gradska četvrt posvećena piščevom djelu, koju je podigao reditelj Emir Kusturica.",
                            DestinationId = new Guid("1a0a0001-0000-4000-8000-000000000010"),
