                            BestTimeToVisit = "May-October",
                            Description = "Višegrad is home to the 1577 Mehmed Paša Sokolović Bridge, a masterpiece of Ottoman architecture and a UNESCO World Heritage Site, immortalized by Ivo Andrić in his Nobel Prize-winning novel \"The Bridge on the Drina.\" Nearby stands Andrićgrad, a stone town quarter built by director Emir Kusturica in tribute to the writer's work.",
                            DestinationId = new Guid("1a0a0001-0000-4000-8000-000000000010"),
                            LanguageCode = "en"
                        },
                        new
                        {
                            Id = new Guid("2a0a0001-0000-4000-8000-000000000021"),
                            BestTimeToVisit = "maj-oktobar",
                            Description = "Jajce je jedini grad na svijetu sa vodopadom usred samog centra — Pliva se sa oko 20 metara visine uliva u Vrbas, tik ispod srednjovjekovne tvrđave koja je nekad bila posljednje uporište nezavisnog Bosanskog kraljevstva. U gradu je 1943. održano drugo zasjedanje AVNOJ-a, kojim je postavljen temelj socijalističke Jugoslavije. Nekoliko kilometara uzvodno, stara vodenice na Plivskim jezerima (\"mlinčići\") dodatno svjedoče o dugoj istoriji ovog malog, ali slojevitog grada.",
                            DestinationId = new Guid("1a0a0001-0000-4000-8000-000000000011"),
                            LanguageCode = "bs"
